#pragma once
namespace snuw {
inline int auditionNetworkTest(const fs::path& folder,const std::string& api){try{auto cfg=defaults(folder);cfg.update({{"api",api},{"_local_workspace_root",utf8(folder.wstring())},{"api_key","audition-key"},{"channel_id",std::string(32,'d')},{"_local_account_scope",std::string(64,'a')},{"_audition_run",std::string(32,'b')},{"_audition_index",0},{"count","1"},{"job_timeout_seconds","10"}});auto state=newState(cfg);state["drafts"]["prompt"]="test";int accepted=0,downloaded=0,terminal=0;auto token=id();for(int pass=0;pass<2;pass++){if(pass)cfg["_audition_job"]=std::string(32,'c');Engine engine;engine.enqueue({std::string(32,'d'),token,cfg,state,false});bool finished=false;std::string error;for(int i=0;i<500&&!finished;i++){for(auto& event:engine.take()){if(event.kind=="audition_job"){accepted++;if(str(event.data,"job")!=std::string(32,'c')||str(event.data,"scope")!=std::string(64,'a'))throw std::runtime_error("Job association failed");}if(event.kind=="audition_image")downloaded++;if(event.kind=="audition_terminal"){terminal++;if(!flag(event.data,"success"))error=str(event.data,"error");}if(event.kind=="error"){error=event.text;finished=true;}if(event.kind=="done")finished=true;}Sleep(10);}if(!finished||!error.empty())throw std::runtime_error("Audition network failed: "+error);}if(accepted!=2||downloaded!=2||terminal!=2)throw std::runtime_error("Audition lifecycle events missing");atomicWrite(folder/"audition-network-result.json",json{{"ok",true},{"accepted",accepted},{"downloaded",downloaded},{"terminal",terminal}}.dump());return 0;}catch(const std::exception& e){atomicWrite(folder/"audition-network-result.json",json{{"ok",false},{"error",e.what()}}.dump());return 1;}}
}
